{
  "headline": "FDA's records trace our rifampin supply to a plant classified OAI 275 days before the shortage posting",
  "headline_cites": ["D4"],
  "sentences": [
    {
      "text": "FDA first posted the rifampin injection shortage on 2021-02-17 and it remains current as of 2026-10-21.",
      "cites": ["E21", "E17"]
    },
    {
      "text": "The product label for NDC 63323-351-20 names Fresenius Kabi USA, LLC as the manufacturing plant (FEI 1450022).",
      "cites": ["E14"]
    },
    {
      "text": "FDA inspection 1123748 at that plant ended 2020-05-18 and was classified OAI, with the classification letter dated 2024-05-22, 275 days before the shortage posting.",
      "cites": ["E11", "D4"]
    },
    {
      "text": "A second OAI inspection (1174894) ended 2022-06-30, 498 days after the posting, with a classification letter dated 2024-04-30.",
      "cites": ["E12", "D5"]
    },
    {
      "text": "The most recent inspection (1216183) ended 2023-08-24 and was classified VAI.",
      "cites": ["E13"]
    },
    {
      "text": "Current inventory across our three sites ranges from 11 to 29 days on hand.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The rule‑selected best option is to buy from Hikma Pharmaceuticals USA Inc., which is not on FDA's shortage list today.",
      "cites": ["D8"]
    }
  ]
}
